// Replays the golden corpus described in work order 003 and updated by
// docs/ENGINE_API.md section 7: one JSON object per line, each recording a
// complete run of intentions against a seed and the exact stateHash and seq
// that run must produce.
//
// The corpus file is generated by tool/generate_corpus.dart and blessed by
// the master after the engine is reviewed. This replayer owns reading it,
// not producing it: a missing or empty corpus file must fail loudly and
// name the path, never pass by iterating over zero records.
//
// docs/ENGINE_API.md section 7 makes "face" mandatory on every "roll"
// record: "A replayer that treats a missing face as anything other than a
// hard failure would silently accept a corpus from before this change and
// prove nothing; it must name the record and fail." That is what
// _parseIntention below does -- no default, no skip, no zero -- and it
// names both the record and the physical line number in the corpus file,
// because "line 17" is what someone actually greps for.
//
// Section 10.5 does the same for a move when the record's rules carry
// rollQueue: face is mandatory there and absent otherwise. rules.rollQueue
// and rules.homeBonus are read when present; absent, the RulesConfig
// default is used, so the 40 legacy lines build the same config they did
// before those keys existed.
//
// LUDO_CORPUS, when set to a non-empty path, is the file replayed instead
// of the committed corpus. The replay suite points it at a file outside
// the repo.
//
// Ambiguity worth flagging for whoever blesses the corpus: the work order's
// example intention objects carry only {"t", "seat", "token"?, "face"?},
// with no documented field for an intention that is expected to be
// rejected. The only existing generator, tool/generate_corpus.dart, never
// records a rejected intention at all (it treats any Rejected result as a
// fixture bug and throws). This replayer follows that: every intention is
// expected to be Applied unless it carries an optional "error" field naming
// an EngineError by its Dart identifier (e.g. "illegalMove"), which is
// supported for forward compatibility but not exercised by anything that
// currently generates this file.

import 'dart:convert';
import 'dart:io';

import 'package:ludo_engine/ludo_engine.dart';
import 'package:test/test.dart';

const String _defaultCorpusPath = 'test/golden/corpus.jsonl';

String _corpusPathFromEnvironment() {
  final fromEnv = Platform.environment['LUDO_CORPUS'];
  if (fromEnv == null || fromEnv.isEmpty) {
    return _defaultCorpusPath;
  }
  return fromEnv;
}

final String _corpusPath = _corpusPathFromEnvironment();

EngineError _parseEngineError(String name) {
  for (final value in EngineError.values) {
    if (value.name == name) {
      return value;
    }
  }
  throw FormatException('unknown EngineError "$name" in golden corpus');
}

/// A rules flag the corpus may omit. Absent yields the [RulesConfig]
/// default for that flag, not a hard-coded stand-in.
bool _optionalRuleFlag(Map<String, Object?> rules, String key) {
  final defaults = const RulesConfig();
  if (!rules.containsKey(key)) {
    return switch (key) {
      'rollQueue' => defaults.rollQueue,
      'homeBonus' => defaults.homeBonus,
      _ => throw ArgumentError('unknown rules flag "$key"'),
    };
  }
  final value = rules[key];
  if (value is! bool) {
    throw FormatException(
      'rules.$key must be a bool when present, got $value',
    );
  }
  return value;
}

GameConfig _parseConfig(Map<String, Object?> record) {
  final rawSeats = record['seats']! as List<Object?>;
  final seats = rawSeats.map((s) => s! as int).toList();
  final rawRules = record['rules']! as Map<String, Object?>;
  final hasRollQueue = rawRules.containsKey('rollQueue');
  final hasHomeBonus = rawRules.containsKey('homeBonus');
  // Neither key: the constructor a legacy record has always taken.
  // rollQueue and homeBonus stay at the RulesConfig defaults.
  final RulesConfig rules;
  if (!hasRollQueue && !hasHomeBonus) {
    rules = RulesConfig(
      blocks: rawRules['blocks']! as bool,
      captureBonus: rawRules['captureBonus']! as bool,
    );
  } else {
    rules = RulesConfig(
      blocks: rawRules['blocks']! as bool,
      captureBonus: rawRules['captureBonus']! as bool,
      rollQueue: _optionalRuleFlag(rawRules, 'rollQueue'),
      homeBonus: _optionalRuleFlag(rawRules, 'homeBonus'),
    );
  }
  final seed = record['seed']! as int;
  return GameConfig(seats: seats, rules: rules, seed: seed);
}

/// Builds the [Intention] for one record of a corpus record's `intentions`
/// list. [recordName] and [physicalLine] (1-based, the line in
/// [_corpusPath] the whole record came from) and [intentionIndex] (0-based,
/// the position of [raw] within that record's `intentions` array) exist so
/// that any failure here names exactly where in the file to look.
Intention _parseIntention(
  Map<String, Object?> raw, {
  required String recordName,
  required int physicalLine,
  required int intentionIndex,
  required bool rollQueue,
}) {
  final type = raw['t']! as String;
  final seat = raw['seat']! as int;
  switch (type) {
    case 'roll':
      final rawFace = raw['face'];
      if (rawFace is! int) {
        throw FormatException(
          'golden corpus line $physicalLine, record "$recordName", '
          'intention $intentionIndex ($raw): a "roll" record has no '
          'integer "face" field. docs/ENGINE_API.md section 7 makes '
          '"face" mandatory on every roll record now that the engine '
          'draws no randomness of its own (rule 38); a corpus recorded '
          'before that change is not valid input to this replayer and '
          'must be regenerated by tool/generate_corpus.dart. Refusing to '
          'default it to anything, including 0.',
        );
      }
      return RollIntention(seat, rawFace);
    case 'move':
      final token = raw['token']! as int;
      final rawFace = raw['face'];
      if (rollQueue) {
        if (rawFace is! int) {
          throw FormatException(
            'golden corpus line $physicalLine, record "$recordName", '
            'intention $intentionIndex ($raw): a "move" record in a '
            'rollQueue game has no integer "face" field. '
            'docs/ENGINE_API.md section 10.5 makes "face" mandatory on '
            'every move intention when rules.rollQueue is true, and absent '
            'on every move intention otherwise.',
          );
        }
        return MoveIntention(seat, token, face: rawFace);
      }
      if (raw.containsKey('face')) {
        throw FormatException(
          'golden corpus line $physicalLine, record "$recordName", '
          'intention $intentionIndex ($raw): a "move" record carries '
          '"face", which docs/ENGINE_API.md section 10.5 allows only when '
          'rules.rollQueue is true.',
        );
      }
      return MoveIntention(seat, token);
    default:
      throw FormatException(
        'golden corpus line $physicalLine, record "$recordName", '
        'intention $intentionIndex ($raw): unknown intention type "$type"',
      );
  }
}

void _replayRecord(Map<String, Object?> record, int physicalLine) {
  final name = record['name']! as String;
  final seed = record['seed']! as int;
  final config = _parseConfig(record);
  final rawIntentions = record['intentions']! as List<Object?>;
  final finalHash = record['finalHash']! as String;
  final finalSeq = record['finalSeq']! as int;

  var state = newGame(config);
  for (var i = 0; i < rawIntentions.length; i++) {
    final raw = rawIntentions[i]! as Map<String, Object?>;
    final intention = _parseIntention(
      raw,
      recordName: name,
      physicalLine: physicalLine,
      intentionIndex: i,
      rollQueue: config.rules.rollQueue,
    );
    final result = apply(state, intention);
    final expectedErrorName = raw['error'] as String?;

    if (expectedErrorName != null) {
      expect(
        result,
        isA<Rejected>(),
        reason: 'game "$name" (seed=$seed, line $physicalLine), intention '
            '$i ($raw): expected a rejection but got $result',
      );
      expect(
        (result as Rejected).error,
        _parseEngineError(expectedErrorName),
        reason: 'game "$name" (seed=$seed, line $physicalLine), intention '
            '$i ($raw)',
      );
      // A rejected intention does not advance state, per
      // docs/ENGINE_API.md section 4.
      continue;
    }

    expect(
      result,
      isA<Applied>(),
      reason: 'game "$name" (seed=$seed, line $physicalLine), intention $i '
          '($raw) was rejected: '
          '${result is Rejected ? result.error : result}',
    );
    state = (result as Applied).state;
  }

  expect(
    stateHash(state),
    finalHash,
    reason: 'game "$name" (seed=$seed, line $physicalLine): final '
        'stateHash does not match the pinned golden value after replaying '
        '${rawIntentions.length} intentions',
  );
  expect(
    state.seq,
    finalSeq,
    reason: 'game "$name" (seed=$seed, line $physicalLine): final seq does '
        'not match the pinned golden value after replaying '
        '${rawIntentions.length} intentions',
  );
}

void main() {
  final file = File(_corpusPath);

  if (!file.existsSync()) {
    test('golden corpus file exists', () {
      fail(
        'golden corpus file not found at "${file.absolute.path}". It is '
        'generated by tool/generate_corpus.dart and blessed by the master '
        'after the engine is reviewed; it does not ship with this test '
        'suite. Generate it, then re-run this test. This failure is '
        'expected and correct until that file exists; it must never be '
        'treated as a pass or a skip.',
      );
    });
    return;
  }

  final rawLines = file.readAsLinesSync();
  // (physical, 1-based line number; record text), skipping blank lines,
  // keeping the physical line number even when blank lines are skipped so
  // every failure names a real line in the file.
  final entries = <(int physicalLine, String content)>[
    for (var i = 0; i < rawLines.length; i++)
      if (rawLines[i].trim().isNotEmpty) (i + 1, rawLines[i]),
  ];

  test('golden corpus file is not empty', () {
    expect(
      entries,
      isNotEmpty,
      reason: 'golden corpus file "${file.absolute.path}" exists but has '
          'zero records. A replay of zero games must not report a pass.',
    );
  });

  for (final (physicalLine, content) in entries) {
    final record = jsonDecode(content) as Map<String, Object?>;
    final name = record['name'] as String? ?? 'line $physicalLine';
    final seed = record['seed'];
    test('golden corpus: $name (seed=$seed, line $physicalLine)', () {
      _replayRecord(record, physicalLine);
    });
  }
}
